begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(i integer) returns void language plpgsql as $$ begin
 perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','37070000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
end $$;
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('37070000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','reimbursement-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,6) i;
select pg_temp.login(1);
create temp table ctx as select public.create_project('Reimbursement fixture','UTC','GBP','2026-01-01') id;
create temp table cat as with c as(insert into public.project_areas(project_id,title) select id,'Villa' from ctx returning id) select * from c;
set local role postgres;
insert into public.project_members(project_id,user_id,display_name,role,status)
select ctx.id,('37070000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Reimbursement member '||i,case when i=4 then 'viewer' else 'member' end::public.member_role,'active' from ctx,generate_series(2,4) i;
create temp table members as select right(user_id::text,1)::int n,id from public.project_members where project_id=(select id from ctx);
grant select on members to authenticated;
select pg_temp.login(1);
create temp table activity as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Villa","kind":"other","activity_type":"task","estimated_cost_minor":90000}',null)).id;
select public.set_activity_cost_split((select id from activity),jsonb_build_object('mode','even','cost',90000,'members',(select jsonb_agg(id order by id) from members where n<=3)));
create temp table payment as with p as(insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,activity.id,members.id,'full','outgoing','paid',90000,current_date from ctx,activity,members where n=1 returning id) select * from p;
insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select ctx.id,activity.id,'Vendor schedule',90000,current_date+30 from ctx,activity;
create temp table before_schedules as select jsonb_agg(to_jsonb(s) order by payment_schedule_id) doc from public.v_activity_payment_schedule_financials s where project_id=(select id from ctx);
create temp table before_financial as select to_jsonb(f) doc from public.v_project_financials f where project_id=(select id from ctx);
create temp table before_balances as select jsonb_agg(to_jsonb(s) order by member_id) doc from public.v_activity_member_settlements s where commitment_id=(select id from activity);
create temp table before_member_balances as select jsonb_agg(to_jsonb(s) order by member_id) doc from public.v_member_balances s where project_id=(select id from ctx);
create temp table before_shares as select jsonb_agg(to_jsonb(s) order by member_id) doc from public.cost_shares s where commitment_id=(select id from activity);
select is((select count(*)::int from public.get_reimbursement_suggestions((select id from payment))),2,'Single payer: two suggestions');
select is((select sum(amount_minor)::bigint from public.get_reimbursement_suggestions((select id from payment))),60000::bigint,'Own share excluded, requested total 600');
select ok(not exists(select 1 from public.get_reimbursement_suggestions((select id from payment)) where debtor_member_id=creditor_member_id),'No self suggestion');
select ok(not exists(select 1 from public.get_reimbursement_suggestions((select id from payment)) where amount_minor<>30000),'Each suggestion uses the existing 300 balance');
select throws_ok($$select public.create_reimbursement((select id from payment),(select id from members where n=1),100)$$,'42501',null,'No self request');
select throws_ok($$select public.create_reimbursement((select id from payment),(select id from members where n=2),0)$$,'P0001',null,'Positive amount');
select throws_ok($$select public.create_reimbursement((select id from payment),(select id from members where n=2),30001)$$,'P0001',null,'Cannot exceed authoritative owed amount');
create temp table request_a as select public.create_reimbursement((select id from payment),(select id from members where n=2),30000) id;
select is(public.create_reimbursement((select id from payment),(select id from members where n=2),30000),(select id from request_a),'Exact retry returns same request');
select throws_ok($$select public.create_reimbursement((select id from payment),(select id from members where n=2),20000)$$,'P0001',null,'Conflicting retry rejected');
create temp table request_b as select public.create_reimbursement((select id from payment),(select id from members where n=3),30000) id;
select is((select count(*)::int from public.get_reimbursement_suggestions((select id from payment))),0,'Open requests reserve capacity without additional suggestions');
select is((select to_jsonb(f) from public.v_project_financials f where project_id=(select id from ctx)),(select doc from before_financial),'Requests do not change cost/spend/refunds');
select is((select jsonb_agg(to_jsonb(s) order by member_id) from public.v_activity_member_settlements s where commitment_id=(select id from activity)),(select doc from before_balances),'No second member balance arithmetic');
select is((select jsonb_agg(to_jsonb(s) order by member_id) from public.v_member_balances s where project_id=(select id from ctx)),(select doc from before_member_balances),'Legacy member balances unchanged');
select is((select jsonb_agg(to_jsonb(s) order by member_id) from public.cost_shares s where commitment_id=(select id from activity)),(select doc from before_shares),'Cost shares untouched');
select is((select jsonb_agg(to_jsonb(s) order by payment_schedule_id) from public.v_activity_payment_schedule_financials s where project_id=(select id from ctx)),(select doc from before_schedules),'Existing schedule amounts and state unchanged');
select is((select count(*)::int from public.v_reimbursements where project_id=(select id from ctx)),2,'Organizer reads both');
select ok(not exists(select 1 from public.v_reimbursements where project_id=(select id from ctx) and needs_review),'Fresh requests reconcile');
select throws_ok($$update public.reimbursement_requests set amount_minor=1 where id=(select id from request_a)$$,'42501',null,'Direct update denied');
select throws_ok($$delete from public.reimbursement_requests where id=(select id from request_a)$$,'42501',null,'Direct deletion denied');
select throws_ok($$insert into public.reimbursement_requests select * from public.reimbursement_requests$$,'42501',null,'Direct insertion denied');
set local role postgres;
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.reimbursement_requests'::regclass),'ENABLE and FORCE RLS');
select throws_ok($$update public.reimbursement_requests set amount_minor=1 where id=(select id from request_a)$$,'P0001',null,'Even trusted core update blocked');
select throws_ok($$update public.reimbursement_requests set payment_id=gen_random_uuid() where id=(select id from request_a)$$,'P0001',null,'Source immutable');
select throws_ok($$update public.reimbursement_requests set creditor_member_id=(select id from members where n=3) where id=(select id from request_a)$$,'P0001',null,'Creditor immutable');
select is((select count(*)::int from app.domain_events where resource_id=(select id from request_a) and event_type='reimbursement.created'),1,'One creation event on retry');
select is((select actor_user_id from app.domain_events where resource_id=(select id from request_a)),'37070000-0000-4000-8000-000000000001'::uuid,'Actor auth derived');
select is((select payload from app.domain_events where resource_id=(select id from request_a)),jsonb_build_object('activity_id',(select id from activity),'payment_id',(select id from payment)),'Minimal event payload');
select is((select count(*)::int from public.notifications where reimbursement_id=(select id from request_a)),1,'One debtor notification');
select is((select recipient_user_id from public.notifications where reimbursement_id=(select id from request_a)),'37070000-0000-4000-8000-000000000002'::uuid,'Only debtor receives');
select app.process_domain_event((select id from app.domain_events where resource_id=(select id from request_a)));
select is((select count(*)::int from public.notifications where reimbursement_id=(select id from request_a)),1,'Processing retry deduplicates');
select is((select count(*)::int from app.domain_event_processing ep join app.domain_events e on e.id=ep.event_id where e.resource_id=(select id from request_a)),1,'One processing receipt');
select is((select count(*)::int from app.automation_action_runs ar join app.domain_events e on e.id=ar.event_id where e.resource_id=(select id from request_a)),1,'One action receipt');
select pg_temp.login(2);
select is((select count(*)::int from public.v_reimbursements where project_id=(select id from ctx)),1,'Debtor reads own request only');
select is((select count(*)::int from public.reimbursement_requests where project_id=(select id from ctx)),1,'Direct row RLS matches restricted read model');
select is((select count(*)::int from public.v_my_reimbursement_notifications where project_id=(select id from ctx)),1,'Debtor inbox');
select is((select count(*)::int from public.get_project_health((select id from ctx)) where subject_type='reimbursement'),1,'Debtor personal attention');
select ok(not exists(select 1 from public.get_project_health((select id from ctx)) where subject_type='reimbursement' and (message~*'due soon|overdue' or affects_health)),'No false urgency or project score impact');
select throws_ok($$select public.get_reimbursement_suggestions((select id from payment))$$,'42501',null,'Unrelated payer cannot inspect create suggestions');
select throws_ok($$select public.create_reimbursement((select id from payment),(select id from members where n=3),100)$$,'42501',null,'Arbitrary Member cannot claim payer funds');
select throws_ok($$select public.cancel_reimbursement((select id from request_a))$$,'42501',null,'Debtor cannot cancel');
select throws_ok($$select app.emit_domain_event('reimbursement.created',(select id from ctx),(select id from request_a),'{}','created')$$,'42501',null,'Client cannot spoof event');
select pg_temp.login(4);
select is((select count(*)::int from public.v_reimbursements where project_id=(select id from ctx)),0,'Unrelated Viewer cannot see sensitive requests');
select throws_ok($$select public.create_reimbursement((select id from payment),(select id from members where n=2),30000)$$,'42501',null,'Viewer cannot create');
select throws_ok($$select public.cancel_reimbursement((select id from request_a))$$,'42501',null,'Viewer cannot cancel');
select pg_temp.login(1);
create temp table access_token as select public.regenerate_project_join_link((select id from ctx)) token;
select pg_temp.login(5);
select public.request_project_access((select token from access_token));
select throws_ok($$select public.create_reimbursement((select id from payment),(select id from members where n=2),30000)$$,'42501',null,'Pending join requester cannot create');
select is((select count(*)::int from public.v_reimbursements where project_id=(select id from ctx)),0,'Nonmember cannot read');
select pg_temp.login(6);
create temp table other as select public.create_project('Other reimbursements','UTC','GBP','2026-01-01') id;
create temp table outsider as select id from public.project_members where project_id=(select id from other);
select is((select count(*)::int from public.v_reimbursements where project_id=(select id from ctx)),0,'Cross-project Organizer cannot read');
select throws_ok($$select public.cancel_reimbursement((select id from request_a))$$,'42501',null,'Cross-project Organizer cannot mutate');
select pg_temp.login(1);
select throws_ok($$select public.create_reimbursement((select id from payment),(select id from outsider),100)$$,'42501',null,'Cross-project debtor denied');
select is((select count(*)::int from public.get_project_health((select id from ctx)) where subject_type='reimbursement'),0,'Creditor gets no duplicate personal attention');
select public.cancel_reimbursement((select id from request_a));
select lives_ok($$select public.cancel_reimbursement((select id from request_a))$$,'Repeat cancellation safe');
select is((select status from public.reimbursement_requests where id=(select id from request_a)),'cancelled','Cancelled lifecycle');
select is((select to_jsonb(f) from public.v_project_financials f where project_id=(select id from ctx)),(select doc from before_financial),'Cancellation leaves ledger totals unchanged');
select pg_temp.login(2);
select is((select count(*)::int from public.v_my_reimbursement_notifications where project_id=(select id from ctx)),0,'Cancelled inbox entry hidden');
select is((select count(*)::int from public.get_project_health((select id from ctx)) where subject_type='reimbursement'),0,'Cancelled attention removed');
select pg_temp.login(1);
-- Refunds stay authoritative; snapshot is retained but no longer asserted as currently owed.
insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,activity.id,members.id,'refund','incoming','paid',30000,current_date from ctx,activity,members where n=1;
select ok((select needs_review from public.v_reimbursements where id=(select id from request_b)),'Refund requires explicit request reconciliation');
select is((select amount_minor from public.reimbursement_requests where id=(select id from request_b)),30000::bigint,'Refund never silently rewrites snapshot');
select throws_ok($$select public.get_reimbursement_suggestions((select id from payment))$$,'P0001',null,'Stale requests must be cancelled before new suggestions');
select pg_temp.login(3);
select is((select count(*)::int from public.get_project_health((select id from ctx)) where subject_type='reimbursement'),0,'Refund removes stale owed claim from attention');
select ok((select needs_review from public.v_my_reimbursement_notifications where project_id=(select id from ctx)),'Notification uses review copy instead of stale claim');
select pg_temp.login(1);
select public.cancel_reimbursement((select id from request_b));
select is((select sum(amount_minor)::bigint from public.get_reimbursement_suggestions((select id from payment))),30000::bigint,'Refund reduces capacity using existing net creditor balance');
-- Multiple payers: source Member paid 600, Organizer paid 300, both shares 300.
create temp table multi as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Multiple payers","kind":"other","activity_type":"task","estimated_cost_minor":90000}',null)).id;
select public.set_activity_cost_split((select id from multi),jsonb_build_object('mode','even','cost',90000,'members',(select jsonb_agg(id order by id) from members where n<=3)));
create temp table multi_payment as with p as(insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,multi.id,members.id,'full','outgoing','paid',case when n=2 then 60000 else 30000 end,current_date from ctx,multi,members where n in(1,2) returning id,paid_by_member_id) select * from p;
select is((select count(*)::int from public.get_reimbursement_suggestions((select id from multi_payment where paid_by_member_id=(select id from members where n=1)))),0,'Payer who only covered own share has no reimbursement');
select pg_temp.login(2);
select is((select amount_minor from public.get_reimbursement_suggestions((select id from multi_payment where paid_by_member_id=(select id from members where n=2)))),30000::bigint,'Multiple payer suggestion matches authoritative 300 credit');
create temp table member_request as select public.create_reimbursement((select id from multi_payment where paid_by_member_id=(select id from members where n=2)),(select id from members where n=3),30000) id;
select lives_ok($$select public.cancel_reimbursement((select id from member_request))$$,'Payer Member may create and cancel own request');
-- Fresh request, then cost-share edit and existing settlement API.
create temp table revised as select public.create_reimbursement((select id from multi_payment where paid_by_member_id=(select id from members where n=2)),(select id from members where n=3),30000) id;
select pg_temp.login(1);
select public.set_activity_cost_split((select id from multi),jsonb_build_object('mode','custom','cost',90000,'members',(select jsonb_agg(id order by id) from members where n<=3),'amounts',(select jsonb_object_agg(id::text,case when n=1 then 20000 when n=2 then 40000 else 30000 end) from members where n<=3)));
select ok((select needs_review from public.v_reimbursements where id=(select id from revised)),'Share edits require explicit reconciliation');
select lives_ok($$select public.record_item_settlement((select id from multi),(select id from members where n=3),(select id from members where n=2),10000,current_date)$$,'Existing settlement API unchanged even with request history');
select is((select remaining_minor from public.v_activity_member_settlements where commitment_id=(select id from multi) and member_id=(select id from members where n=3)),20000::bigint,'Settlement pair still reduces authoritative remaining');
select public.cancel_reimbursement((select id from revised));
-- Removal and Viewer party reads retain history but do not broaden mutation rights.
update public.project_members set role='viewer' where id=(select id from members where n=3);
select pg_temp.login(3);
select is((select count(*)::int from public.v_reimbursements where id=(select id from request_b)),1,'Viewer party may read own historical request');
select throws_ok($$select public.cancel_reimbursement((select id from request_b))$$,'42501',null,'Viewer party cannot cancel');
select pg_temp.login(1);
update public.project_members set role='member',status='removed' where id=(select id from members where n=3);
select pg_temp.login(3);
select is((select count(*)::int from public.v_reimbursements where project_id=(select id from ctx)),0,'Removed member cannot read historical requests');
select throws_ok($$select public.cancel_reimbursement((select id from request_b))$$,'42501',null,'Removed member cannot mutate');
select pg_temp.login(1);
update public.project_members set status='active' where id=(select id from members where n=3);
-- Partial payment does not create debts beyond payer credit.
create temp table partial as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Partial payer","kind":"other","activity_type":"task","estimated_cost_minor":90000}',null)).id;
select public.set_activity_cost_split((select id from partial),jsonb_build_object('mode','even','cost',90000,'members',(select jsonb_agg(id order by id) from members where n<=3)));
create temp table partial_payment as with p as(insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,partial.id,members.id,'full','outgoing','paid',40000,current_date from ctx,partial,members where n=1 returning id) select * from p;
select is((select sum(amount_minor)::bigint from public.get_reimbursement_suggestions((select id from partial_payment))),10000::bigint,'Partial payer can request only current credit, not gross payment');
create temp table planned as with p as(insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,due_on) select ctx.id,partial.id,members.id,'full','outgoing','scheduled',100,current_date+30 from ctx,partial,members where n=1 returning id) select * from p;
select throws_ok($$select public.get_reimbursement_suggestions((select id from planned))$$,'42501',null,'Planned payment is not an actual reimbursement source');
select throws_ok($$select public.get_reimbursement_suggestions((select id from public.payments where project_id=(select id from ctx) and type='refund' limit 1))$$,'42501',null,'Refund cannot be a reimbursement source');
select throws_ok($$select public.get_reimbursement_suggestions((select id from public.payments where project_id=(select id from ctx) and settlement_group_id is not null limit 1))$$,'42501',null,'Settlement transfer cannot be a reimbursement source');
create temp table partial_request as select public.create_reimbursement((select id from partial_payment),(select debtor_member_id from public.get_reimbursement_suggestions((select id from partial_payment)) limit 1),10000) id;
update public.projects set status='archived' where id=(select id from ctx);
select is((select count(*)::int from public.v_reimbursements where id=(select id from partial_request)),1,'Archived request readable');
select throws_ok($$select public.cancel_reimbursement((select id from partial_request))$$,'42501',null,'Archive cancellation denied');
select throws_ok($$select public.create_reimbursement((select id from partial_payment),(select id from members where n=2),1)$$,'42501',null,'Archive creation denied');
update public.projects set status='active' where id=(select id from ctx);
select lives_ok($$select public.soft_delete_project((select id from ctx))$$,'Normal project cleanup unaffected');
set constraints all immediate;
select is((select count(*)::int from public.v_reimbursements where project_id=(select id from ctx)),0,'Deleted parents hide read model');
select is((select count(*)::int from public.reimbursement_requests where project_id=(select id from ctx)),0,'Deleted parents hide table rows');
set local role postgres;
select ok(exists(select 1 from public.reimbursement_requests where project_id=(select id from ctx)),'Historical requests retained');
select ok(exists(select 1 from public.audit_log where project_id=(select id from ctx) and entity_type='reimbursement_requests'),'Financial audit retained');
select ok(exists(select 1 from app.domain_events where project_id=(select id from ctx) and event_type='reimbursement.cancelled'),'Cancellation fact retained');
set local role anon;
select throws_ok($$select * from public.v_reimbursements$$,'42501',null,'Anonymous view denied');
select throws_ok($$select public.create_reimbursement(null,null,1)$$,'42501',null,'Anonymous mutation denied');
select * from finish();
rollback;
